import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { registerUser, clearError, selectIsLoading, selectError } from '../authSlice';
import Modal from '../../../shared/components/Modal';

const Register = ({ isOpen, onClose, onSwitchToLogin }) => {
  const dispatch = useDispatch();
  const isLoading = useSelector(selectIsLoading);
  const error = useSelector(selectError);
  
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phoneNumber: '',
    useEmail: true,
    month: '',
    day: '',
    year: '',
  });

  const [currentStep, setCurrentStep] = useState(1);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    // Clear error when user starts typing
    if (error) {
      dispatch(clearError());
    }
  };

  const handleToggleEmail = () => {
    setFormData(prev => ({
      ...prev,
      useEmail: !prev.useEmail,
      phoneNumber: '',
      email: ''
    }));
  };

  const handleNext = () => {
    if (currentStep < 3) {
      setCurrentStep(currentStep + 1);
    }
  };

  const handleBack = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const userData = {
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email,
        phoneNumber: formData.phoneNumber,
        dateOfBirth: `${formData.year}-${formData.month}-${formData.day}`,
        useEmail: formData.useEmail
      };
      
      await dispatch(registerUser(userData)).unwrap();
      onClose();
      // Reset form
      setFormData({
        firstName: '',
        lastName: '',
        email: '',
        phoneNumber: '',
        useEmail: true,
        month: '',
        day: '',
        year: '',
      });
      setCurrentStep(1);
    } catch (error) {
      // Error is handled by Redux
    }
  };

  const handleClose = () => {
    dispatch(clearError());
    setFormData({
      firstName: '',
      lastName: '',
      email: '',
      phoneNumber: '',
      useEmail: true,
      month: '',
      day: '',
      year: '',
    });
    setCurrentStep(1);
    onClose();
  };

  const renderStep1 = () => (
    <div className="space-y-6">
      {/* Username field */}
      <div>
        <label htmlFor="firstName" className="block text-sm font-medium text-gray-700 mb-2">
          Your username
        </label>
        <input
          type="text"
          id="firstName"
          name="firstName"
          value={formData.firstName}
          onChange={handleInputChange}
          className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          placeholder="Enter your username"
          required
        />
      </div>

      {/* Phone number field */}
      <div>
        <label htmlFor="phoneNumber" className="block text-sm font-medium text-gray-700 mb-2">
          Phone number
        </label>
        <div className="flex gap-2">
          <select className="px-3 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
            <option value="+1">🇺🇸 +1</option>
            <option value="+84">🇻🇳 +84</option>
            <option value="+44">🇬🇧 +44</option>
          </select>
          <input
            type="tel"
            id="phoneNumber"
            name="phoneNumber"
            value={formData.phoneNumber}
            onChange={handleInputChange}
            className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="Phone number"
            disabled={formData.useEmail}
          />
        </div>
        <div className="text-right mt-2">
          <button
            type="button"
            onClick={handleToggleEmail}
            className="text-blue-600 hover:text-blue-700 text-sm font-medium"
          >
            Use Email instead
          </button>
        </div>
      </div>

      {/* Date of birth */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          What's your date of birth?
        </label>
        <div className="grid grid-cols-3 gap-2">
          <select
            name="month"
            value={formData.month}
            onChange={handleInputChange}
            className="px-3 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            required
          >
            <option value="">Month</option>
            <option value="01">January</option>
            <option value="02">February</option>
            <option value="03">March</option>
            <option value="04">April</option>
            <option value="05">May</option>
            <option value="06">June</option>
            <option value="07">July</option>
            <option value="08">August</option>
            <option value="09">September</option>
            <option value="10">October</option>
            <option value="11">November</option>
            <option value="12">December</option>
          </select>
          <select
            name="day"
            value={formData.day}
            onChange={handleInputChange}
            className="px-3 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            required
          >
            <option value="">Date</option>
            {Array.from({ length: 31 }, (_, i) => (
              <option key={i + 1} value={String(i + 1).padStart(2, '0')}>
                {i + 1}
              </option>
            ))}
          </select>
          <select
            name="year"
            value={formData.year}
            onChange={handleInputChange}
            className="px-3 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            required
          >
            <option value="">Year</option>
            {Array.from({ length: 100 }, (_, i) => {
              const year = new Date().getFullYear() - i;
              return (
                <option key={year} value={year}>
                  {year}
                </option>
              );
            })}
          </select>
        </div>
      </div>
    </div>
  );

  const renderStep2 = () => (
    <div className="space-y-6">
      <div className="text-center">
        <h3 className="text-lg font-semibold text-gray-900 mb-2">Step 2 Content</h3>
        <p className="text-gray-600">Additional registration information would go here.</p>
      </div>
    </div>
  );

  const renderStep3 = () => (
    <div className="space-y-6">
      <div className="text-center">
        <h3 className="text-lg font-semibold text-gray-900 mb-2">Step 3 Content</h3>
        <p className="text-gray-600">Final registration confirmation would go here.</p>
      </div>
    </div>
  );

  const isStep1Valid = formData.firstName && formData.month && formData.day && formData.year;

  return (
    <Modal isOpen={isOpen} onClose={handleClose} className="p-8">
      {/* Step indicator */}
      <div className="flex justify-center mb-6">
        <div className="w-3 h-3 bg-gray-300 rounded-full"></div>
      </div>

      {/* Tab selector */}
      <div className="flex bg-gray-100 rounded-lg p-1 mb-8">
        <button
          className="flex-1 py-2 px-4 bg-gray-900 text-white rounded-md transition-colors"
        >
          Sign up
        </button>
        <button
          onClick={onSwitchToLogin}
          className="flex-1 py-2 px-4 text-gray-600 rounded-md transition-colors"
        >
          Log in
        </button>
      </div>

      {/* Title */}
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold text-gray-900">Sign up</h2>
        <p className="text-gray-600 mt-2">Step {currentStep} of 3</p>
      </div>

      {/* Social signup buttons */}
      {currentStep === 1 && (
        <>
          <div className="space-y-4 mb-8">
            <button className="w-full flex items-center justify-center px-4 py-3 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors">
              <svg className="w-5 h-5 mr-3" viewBox="0 0 24 24">
                <path fill="#1877F2" d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z"/>
              </svg>
              <span className="text-gray-900 font-medium">Sign up with Facebook</span>
            </button>

            <button className="w-full flex items-center justify-center px-4 py-3 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors">
              <svg className="w-5 h-5 mr-3" viewBox="0 0 24 24">
                <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
              </svg>
              <span className="text-gray-900 font-medium">Sign up with Google</span>
            </button>
          </div>

          {/* OR divider */}
          <div className="flex items-center mb-8">
            <div className="flex-1 h-px bg-gray-300"></div>
            <span className="px-4 text-gray-500 text-sm">OR</span>
            <div className="flex-1 h-px bg-gray-300"></div>
          </div>

          {/* Email instruction */}
          <p className="text-gray-600 text-sm text-center mb-6">
            Enter your email address to create an account.
          </p>
        </>
      )}

      {/* Form content based on step */}
      <form onSubmit={currentStep === 3 ? handleSubmit : (e) => { e.preventDefault(); handleNext(); }} className="space-y-6">
        {currentStep === 1 && renderStep1()}
        {currentStep === 2 && renderStep2()}
        {currentStep === 3 && renderStep3()}

        {/* Error message */}
        {error && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-3">
            <p className="text-red-600 text-sm">{error}</p>
          </div>
        )}

        {/* Navigation buttons */}
        <div className="flex gap-4">
          {currentStep > 1 && (
            <button
              type="button"
              onClick={handleBack}
              className="flex-1 py-3 px-6 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium transition-colors"
            >
              Back
            </button>
          )}
          
          {currentStep < 3 ? (
            <button
              type="submit"
              disabled={currentStep === 1 && !isStep1Valid}
              className="flex-1 bg-gray-900 text-white py-3 px-6 rounded-lg font-medium hover:bg-gray-800 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors"
            >
              Next
            </button>
          ) : (
            <button
              type="submit"
              disabled={isLoading}
              className="flex-1 bg-gray-900 text-white py-3 px-6 rounded-lg font-medium hover:bg-gray-800 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors"
            >
              {isLoading ? 'Creating account...' : 'Create an account'}
            </button>
          )}
        </div>
      </form>
    </Modal>
  );
};

export default Register;