import React, { useState } from 'react';
import { NavBar, Footer } from '../../../shared';
import Login from './Login';
import Register from './Register';

const AuthPage = () => {
  const [activeModal, setActiveModal] = useState(null); // 'login' or 'register'

  const openLogin = () => setActiveModal('login');
  const openRegister = () => setActiveModal('register');
  const closeModal = () => setActiveModal(null);

  const switchToRegister = () => setActiveModal('register');
  const switchToLogin = () => setActiveModal('login');

  return (
    <div className="min-h-screen flex flex-col">
      <NavBar onLoginClick={openLogin} onRegisterClick={openRegister} />
      
      {/* Main content with gradient background */}
      <main className="flex-1 relative">
        {/* Gradient background */}
        <div className="absolute inset-0 bg-gradient-to-br from-purple-400 via-pink-500 to-red-500 opacity-20"></div>
        
        {/* Center content */}
        <div className="relative z-10 flex items-center justify-center min-h-full">
          <div className="text-center">
            <h1 className="text-6xl font-bold text-gray-800 mb-4">Welcome to MORENT</h1>
            <p className="text-xl text-gray-600 mb-8">Your car rental platform</p>
            <div className="space-x-4">
              <button
                onClick={openLogin}
                className="px-8 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
              >
                Log In
              </button>
              <button
                onClick={openRegister}
                className="px-8 py-3 bg-gray-900 text-white rounded-lg hover:bg-gray-800 transition-colors font-medium"
              >
                Sign Up
              </button>
            </div>
          </div>
        </div>
      </main>

      <Footer />

      {/* Modals */}
      <Login 
        isOpen={activeModal === 'login'} 
        onClose={closeModal}
        onSwitchToRegister={switchToRegister}
      />
      <Register 
        isOpen={activeModal === 'register'} 
        onClose={closeModal}
        onSwitchToLogin={switchToLogin}
      />
    </div>
  );
};

export default AuthPage;
